const form=document.getElementById("vacationForm"),result=document.getElementById("result");form&&form.addEventListener("submit",s=>{s.preventDefault();const i=document.getElementById("salaryBasis").value,n=parseFloat(document.getElementById("salary").value)||0,c=parseFloat(document.getElementById("days").value)||28,t=i==="net"?n/.87:n,e=t/29.3,a=e*c,l=a*.13,o=a-l;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Зарплата (начислено)</span><span class="val">${fmt(t)} ₽</span></div>
        <div class="item"><span>Средний дневной заработок</span><span class="val">${fmt(e)} ₽</span></div>
        <div class="item"><span>Отпускные (начислено)</span><span class="val">${fmt(a)} ₽</span></div>
        <div class="item"><span>НДФЛ 13%</span><span class="val">− ${fmt(l)} ₽</span></div>
        <div class="item total"><span>На руки</span><span class="val">${fmt(o)} ₽</span></div>
      </div>
      <p class="hint" style="margin-top:14px">Отпускные считаются от <strong>начисленной</strong> (до НДФЛ) зарплаты. Если ввели сумму «на руки», мы пересчитали её обратно в начисленную.</p>
    `});function fmt(s){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(s)}
